import sys

def solve():
    input = sys.stdin.readline

    N = int(input())
    adj = [[0] * N for _ in range(N)]
    in_degree = [0] * N

    for i in range(N):
        row = input().strip()
        for j in range(N):
            adj[i][j] = int(row[j])
            if adj[i][j]:
                in_degree[j] += 1

    # Find lexicographically smallest topological ordering using Kahn's algorithm with min-heap
    heap = []
    for i in range(N):
        if in_degree[i] == 0:
            heappush(heap, i)

    topo_order = []
    while heap:
        u = heappop(heap)
        topo_order.append(u)
        for v in range(N):
            if adj[u][v]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heappush(heap, v)

    # Add all forward edges that don't exist in the topological ordering
    edges_to_add = []
    for i in range(N):
        for j in range(i + 1, N):
            u, v = topo_order[i], topo_order[j]
            if adj[u][v] == 0:
                edges_to_add.append((u + 1, v + 1))

    # Sort edges lexicographically
    edges_to_add.sort()

    print(len(edges_to_add))
    for u, v in edges_to_add:
