def solve():
    input_data = sys.stdin.read().split()
    idx = 0

    n = int(input_data[idx]); idx += 1
    m = int(input_data[idx]); idx += 1

    a = []
    for i in range(n):
        row = []
        for j in range(m):
            row.append(int(input_data[idx])); idx += 1
        a.append(row)

    q = int(input_data[idx]); idx += 1

    queries = []
    for _ in range(q):
        r1 = int(input_data[idx]); idx += 1
        c1 = int(input_data[idx]); idx += 1
        r2 = int(input_data[idx]); idx += 1
        c2 = int(input_data[idx]); idx += 1
        queries.append((r1, c1, r2, c2))

    # Precompute within_col[c][r1][r2] = sum of a[i][c] for i between r1 and r2 (inclusive)
    within_col = [[[0] * n for _ in range(n)] for _ in range(m)]

    for c in range(m):
        for r1 in range(n):
            for r2 in range(n):
                lo, hi = min(r1, r2), max(r1, r2)
                total = 0
                for i in range(lo, hi + 1):
                    total += a[i][c]
                within_col[c][r1][r2] = total

    # Cache for DP results: key = (c1, c2), value = dp table (n x n where dp[r1][r2] = min cost from (r1,c1) to (r2,c2))
    cache = {}

    def compute_dp(c1, c2):
        """Compute min cost from any (r1, c1) to any (r2, c2) where c1 <= c2"""
        if c1 == c2:
            # Just vertical movement within column c1
            result = [[0] * n for _ in range(n)]
            for r1 in range(n):
                for r2 in range(n):
                    result[r1][r2] = within_col[c1][r1][r2]
            return result

        if c1 > c2:
            c1, c2 = c2, c1

        key = (c1, c2)
        if key in cache:
            return cache[key]

        # DP: dp[r] = min cost to reach (r, c) from some starting row in c1
        # We need to compute for all starting rows in c1

        # result[r1][r2] = min cost from (r1, c1) to (r2, c2)
        result = [[0] * n for _ in range(n)]

        for start_r in range(n):
            # dp[r] = min cost from (start_r, c1) to (r, c)
            dp = [within_col[c1][start_r][r] for r in range(n)]

            for c in range(c1 + 1, c2 + 1):
                new_dp = [float('inf')] * n
                for r in range(n):
                    for prev_r in range(n):
                        cost = dp[prev_r] + within_col[c][prev_r][r]
                        if cost < new_dp[r]:
                            new_dp[r] = cost
                dp = new_dp

            for end_r in range(n):
                result[start_r][end_r] = dp[end_r]

        cache[key] = result
        return result

    results = []
    for r1, c1, r2, c2 in queries:
        if c1 == c2:
            ans = within_col[c1][r1][r2]
        elif c1 < c2:
            dp_table = compute_dp(c1, c2)
            ans = dp_table[r1][r2]
        else:
            # c1 > c2, swap and compute
            dp_table = compute_dp(c2, c1)
            ans = dp_table[r2][r1]

        results.append(str(ans))

    print('\n'.join(results))

solve()
