long long findLCA(long long u, long long v) {
    while (u != v) {
        if (u > v) u /= 2;
        else v /= 2;
    }
    return u;
}

void updatePath(long long u, long long v, long long w) {
    long long lca = findLCA(u, v);

    // Walk from u to LCA
    while (u != lca) {
        edgeWeight[u] += w;
        u /= 2;
    }

    // Walk from v to LCA
    while (v != lca) {
        edgeWeight[v] += w;
        v /= 2;
    }
}

long long queryPath(long long u, long long v) {
    long long lca = findLCA(u, v);
    long long sum = 0;

    // Walk from u to LCA
    while (u != lca) {
        if (edgeWeight.count(u)) {
            sum += edgeWeight[u];
        }
        u /= 2;
    }

    // Walk from v to LCA
    while (v != lca) {
        if (edgeWeight.count(v)) {
            sum += edgeWeight[v];
        }
        v /= 2;
    }

    return sum;
}

