Here is the solution to the problem. The logic is based on constructing pairs $(b_i, g_i)$ such that the difference $(g_i - b_i) \pmod k$ is constant for a block of pairs, and then changing the difference for the next block. This ensures that adjacent pairs differ in both components.

```cpp
#include <iostream>

using namespace std;

int main() {
    // Optimize standard I/O operations for speed
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    // The maximum number of distinct pairs (b, g) with b != g is k * (k - 1).
    // We use long long to prevent integer overflow during multiplication.
    long long max_pairs = (long long)k * (k - 1);

    if (n > max_pairs) {
        cout << "NO" << "\n";
    } else {
        cout << "YES" << "\n";
        int count = 0;
        // Iterate through all possible shifts (differences) d from 1 to k-1
        for (int d = 1; d < k; ++d) {
            // For each shift, iterate through all starting points i from 0 to k-1
            for (int i = 0; i < k; ++i) {
                if (count == n) return 0;

                // Construct the pair. 
                // We use 0-based indexing for calculation and convert to 1-based for output.
                // Man's color: i + 1
                // Woman's color: (i + d) % k + 1
                int man_color = i + 1;
                int woman_color = (i + d) % k + 1;

                cout << man_color << " " << woman_color << "\n";
                count++;
            }
        }
    }
    return 0;
}
