#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

struct State {
    int len, link;
    int cnt;
    map<char, int> next;
};

const int MAXN = 100005;
State st[MAXN * 2];
int sz, last;

void sa_init() {
    st[0].len = 0;
    st[0].link = -1;
    st[0].cnt = 0;
    sz = 1;
    last = 0;
}

void sa_extend(char c) {
    int cur = sz++;
    st[cur].len = st[last].len + 1;
    st[cur].cnt = 1;
    st[cur].next.clear();
    int p = last;
    while (p != -1 && !st[p].next.count(c)) {
        st[p].next[c] = cur;
        p = st[p].link;
    }
    if (p == -1) {
        st[cur].link = 0;
    } else {
        int q = st[p].next[c];
        if (st[p].len + 1 == st[q].len) {
            st[cur].link = q;
        } else {
            int clone = sz++;
            st[clone].len = st[p].len + 1;
            st[clone].next = st[q].next;
            st[clone].link = st[q].link;
            st[clone].cnt = 0;
            while (p != -1 && st[p].next[c] == q) {
                st[p].next[c] = clone;
                p = st[p].link;
            }
            st[q].link = st[cur].link = clone;
        }
    }
    last = cur;
}

int main() {
    string s;
    cin >> s;
    sa_init();
    for (char c : s) {
        sa_extend(c);
    }

    vector<int> order(sz);
    for (int i = 0; i < sz; i++) order[i] = i;
    sort(order.begin(), order.end(), [](int a, int b) {
        return st[a].len > st[b].len;
    });

    for (int i : order) {
        if (st[i].link != -1) {
            st[st[i].link].cnt += st[i].cnt;
        }
    }

    long long ans = 0;
    for (int i = 1; i < sz; i++) {
        long long cnt = st[i].cnt;
        long long num_substrings = st[i].len - st[st[i].link].len;
        ans += num_substrings * cnt * (cnt + 1) / 2;
    }

    cout << ans << endl;
    return 0;
}
