#include <cstdio>
#include <vector>
#include <queue>
using namespace std;

const int MAXN = 1005;
int grid[MAXN][MAXN];
int component[MAXN][MAXN]; // component id for each cell
int componentSize[MAXN * MAXN]; // size of each component
bool componentBurnt[MAXN * MAXN]; // whether component is burnt
int N, M, Q;
int totalNations = 0;
int numComponents = 0;

int dx[] = {-1, 1, 0, 0};
int dy[] = {0, 0, -1, 1};

void bfs(int startR, int startC, int compId) {
    queue<pair<int,int>> q;
    q.push({startR, startC});
    component[startR][startC] = compId;
    componentSize[compId] = 1;

    while (!q.empty()) {
        pair<int,int> curr = q.front();
        q.pop();

        for (int i = 0; i < 4; i++) {
            int nr = curr.first + dx[i];
            int nc = curr.second + dy[i];

            if (nr >= 0 && nr < N && nc >= 0 && nc < M && 
                grid[nr][nc] == 1 && component[nr][nc] == 0) {
                component[nr][nc] = compId;
                componentSize[compId]++;
                q.push({nr, nc});
            }
        }
    }
}

int main() {
    scanf("%d %d %d", &N, &M, &Q);

    // Read grid and count nations
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            scanf("%d", &grid[i][j]);
            if (grid[i][j] == 1) {
                totalNations++;
            }
        }
    }

    // Find connected components
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            if (grid[i][j] == 1 && component[i][j] == 0) {
                numComponents++;
                bfs(i, j, numComponents);
            }
        }
    }

    // Process queries
    for (int q = 0; q < Q; q++) {
        int x, y;
        scanf("%d %d", &x, &y);
        x--; y--; // Convert to 0-indexed

        if (x >= 0 && x < N && y >= 0 && y < M && 
            grid[x][y] == 1 && !componentBurnt[component[x][y]]) {
            int compId = component[x][y];
            componentBurnt[compId] = true;
            totalNations -= componentSize[compId];
        }

        printf("%d\n", totalNations);
    }

    return 0;
}
