Looking at this problem, I need to partition n shipments into two groups A and B to minimize D(A) + D(B), where D(S) is the maximum distance between any pair in subset S.

**Key Insight:** This can be modeled as a 2-SAT problem. For thresholds t1 and t2:
- If d(i,j) > t1: shipments i and j cannot both be in A
- If d(i,j) > t2: shipments i and j cannot both be in B

Using 2-SAT with implication graphs, I can check if a valid partition exists for given (t1, t2).

**Algorithm:**
1. Collect all O(n²) distance values as candidates
2. For each candidate t1, binary search for minimum t2 where 2-SAT is satisfiable
3. Also consider the case where one group is empty (answer = max distance)
4. Return minimum t1 + t2

**Complexity:** O(n⁴ log n) which is acceptable for n ≤ 200

```python
import sys
sys.setrecursionlimit(10000)

def solve():
    n = int(input())

    if n <= 1:
        print(0)
        return

    d = [[0] * n for _ in range(n)]

    for i in range(n - 1):
        row = list(map(int, input().split()))
        for j, val in enumerate(row):
            d[i][i + 1 + j] = val
            d[i + 1 + j][i] = val

    distances = set()
    for i in range(n):
        for j in range(i + 1, n):
            distances.add(d[i][j])

    if not distances:
        print(0)
        return

    distances = sorted(distances)

    def can_partition(t1, t2):
        graph = [[] for _ in range(2 * n)]

        for i in range(n):
            for j in range(i + 1, n):
                if d[i][j] > t1:
                    graph[2 * i + 1].append(2 * j)
                    graph[2 * j + 1].append(2 * i)
                if d[i][j] > t2:
                    graph[2 * i].append(2 * j + 1)
                    graph[2 * j].append(2 * i + 1)

        visited = [False] * (2 * n)
        order = []

        def dfs1(v):
            visited[v] = True
            for u in graph[v]:
                if not visited[u]:
                    dfs1(u)
            order.append(v)

        for v in range(2 * n):
            if not visited[v]:
                dfs1(v)

        rev_graph = [[] for _ in range(2 * n)]
        for v in range(2 * n):
            for u in graph[v]:
                rev_graph[u].append(v)

        visited = [False] * (2 * n)
        component = [-1] * (2 * n)

        def dfs2(v, c):
            visited[v] = True
            component[v] = c
            for u in rev_graph[v]:
                if not visited[u]:
                    dfs2(u, c)

        c = 0
        for v in reversed(order):
            if not visited[v]:
                dfs2(v, c)
                c += 1

        for i in range(n):
            if component[2 * i] == component[2 * i + 1]:
                return False

        return True

    min_sum = distances[-1]

    for t1 in distances:
        lo, hi = 0, len(distances) - 1
        best_t2 = None

        while lo <= hi:
            mid = (lo + hi) // 2
            t2 = distances[mid]
            if can_partition(t1, t2):
                best_t2 = t2
                hi = mid - 1
            else:
                lo = mid + 1

        if best_t2 is not None:
            min_sum = min(min_sum, t1 + best_t2)

    print(min_sum)

solve()
